int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<long long> lastValue(n);
    for (auto &x : lastValue) cin >> x;
    vector<int> typ(m);
    vector<long long> p(m), x(m);
    for (int i = 0; i < m; i++) cin >> typ[i] >> p[i] >> x[i];
    // suffix[t] = largest type-2 target among operations t+1..m (operation t+1 is index t)
    vector<long long> suffix(m + 1, 0);
    for (int i = m - 1; i >= 0; i--) suffix[i] = max(suffix[i + 1], typ[i] == 2 ? x[i] : 0LL);
    vector<int> lastAssignment(n, 0);  // initial values are assigned at time 0
    for (int i = 0; i < m; i++)
        if (typ[i] == 1) {
            lastValue[p[i] - 1] = x[i];
            lastAssignment[p[i] - 1] = i + 1;
        }
    string out;
    for (int i = 0; i < n; i++) {
        if (i) out += ' ';
        out += to_string(max(lastValue[i], suffix[lastAssignment[i]]));
    }
    out += '\n';
    fwrite(out.data(), 1, out.size(), stdout);
