import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        long[] lastValue = new long[n];
        for (int i = 0; i < n; i++) lastValue[i] = nextLong();
        int[] typ = new int[m], p = new int[m];
        long[] x = new long[m];
        for (int i = 0; i < m; i++) {
            typ[i] = nextInt();
            p[i] = nextInt();
            x[i] = nextLong();
        }
        // suffix[t]: largest type-2 target among operations with index >= t
        long[] suffix = new long[m + 1];
        for (int i = m - 1; i >= 0; i--) suffix[i] = Math.max(suffix[i + 1], typ[i] == 2 ? x[i] : 0);
        int[] lastAssignment = new int[n]; // initial values are assigned at time 0
        for (int i = 0; i < m; i++)
            if (typ[i] == 1) {
                lastValue[p[i] - 1] = x[i];
                lastAssignment[p[i] - 1] = i + 1;
            }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(Math.max(lastValue[i], suffix[lastAssignment[i]]));
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, m := int(nextInt()), int(nextInt())
	lastValue := make([]int64, n)
	for i := range lastValue {
		lastValue[i] = nextInt()
	}
	typ := make([]int64, m)
	p := make([]int64, m)
	x := make([]int64, m)
	for i := 0; i < m; i++ {
		typ[i], p[i], x[i] = nextInt(), nextInt(), nextInt()
	}
	// suffix[t]: largest type-2 target among operations with index >= t
	suffix := make([]int64, m+1)
	for i := m - 1; i >= 0; i-- {
		suffix[i] = suffix[i+1]
		if typ[i] == 2 && x[i] > suffix[i] {
			suffix[i] = x[i]
		}
	}
	lastAssignment := make([]int, n) // initial values are assigned at time 0
	for i := 0; i < m; i++ {
		if typ[i] == 1 {
			lastValue[p[i]-1] = x[i]
			lastAssignment[p[i]-1] = i + 1
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < n; i++ {
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.FormatInt(max(lastValue[i], suffix[lastAssignment[i]]), 10))
	}
	w.WriteByte('\n')
}
